// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Read the version": "in1_Readtheversion", "Read the table rows": "in2_Readthetablerows", "Read the threshold list": "in3_Readthethresholdlist", "Read versions": "in4_Readversions", "Read earlier rows": "in5_Readearlierrows"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Read earlier rows";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
// Steps 4 and 6: the alert text, the n8n build's own JavaScript; $(...) answers with this measure's outcome.
const alertText = (measure) => {
  const $ = () => ({ item: { json: measure } });
// Steps 4 and 6: the alert text. It explains nothing and suggests no action.
const o = $('Step 2: Rule: each measure\'s outcome').item.json;
if (o.outcome === 'stale') {
  return { json: { to: o.data_owner, kind: 'stale',
    subject: `Weekly figures: ${o.measure} is ${o.status}`,
    text: `${o.measure} printed blank (${o.status}) at the ${o.cutoff} cut-off. Source: ${o.source} ${o.source_link || ''}. Last good: ${o.last_good || 'none'}.` } };
}
const cmp = (o.direction === 'above' ? (o.inclusive ? 'at or above' : 'above') : (o.inclusive ? 'at or below' : 'below'));
return { json: { to: o.measure_owner, kind: 'past the line',
  subject: `Weekly figures: ${o.measure} is past your line`,
  text: `${o.measure}: value ${o.value}, change ${o.change === null ? 'none' : o.change}; your line is ${o.field} ${cmp} ${o.line} (line version ${o.line_version}). Cut-off ${o.cutoff}. Source: ${o.source_link}` } };
};
const BODIES = (out) => ({"alert": ['stale', 'past the line'].includes(out.outcome) ? 'yes' : 'no', "key_q": encodeURIComponent(out.key), "reserve_body": JSON.stringify({ p_recipe: 'R12.3', p_key: out.key }), "post_body": JSON.stringify((a => ({ to: a.to, subject: a.subject, text: a.text }))((['stale', 'past the line'].includes(out.outcome) ? alertText(out).json : {}))), "alert_log_body": JSON.stringify((a => ({ id: out.key, week: out.week, measure: out.measure, outcome: out.outcome, to: a.to, subject: a.subject, cutoff: out.cutoff, seen: false }))((['stale', 'past the line'].includes(out.outcome) ? alertText(out).json : {}))), "done_body": JSON.stringify({ status: 'done', result: (['stale', 'past the line'].includes(out.outcome) ? alertText(out).json : {}).kind + ' alert sent' }), "log_sent": JSON.stringify({ recipe: 'R12.3', item: out.week + ':' + out.measure, decision: out.outcome + ': alert sent', rules: { version: out.version, value: out.value, change: out.change, status: out.status, line_version: out.line_version, line: out.line, field: out.field, direction: out.direction } }), "log_none": JSON.stringify({ recipe: 'R12.3', item: out.week + ':' + out.measure, decision: out.outcome + ': no alert', rules: { version: out.version, value: out.value, change: out.change, status: out.status, line_version: out.line_version, line: out.line, field: out.field, direction: out.direction } }), "log_copy": JSON.stringify({ recipe: 'R12.3', item: out.week + ':' + out.measure, decision: out.outcome + ': alert suppressed, outcome unchanged', rules: { version: out.version, value: out.value, change: out.change, status: out.status, line_version: out.line_version, line: out.line, field: out.field, direction: out.direction } }), "failed_key_body": JSON.stringify({ status: 'failed', result: 'alert failed' }), "failed_body": JSON.stringify({ recipe: 'R12.3', item: out.week + ':' + out.measure, reason: 'alert failed', detail: 'Post and email failed for ' + (['stale', 'past the line'].includes(out.outcome) ? alertText(out).json : {}).to + '; reassign the measure or fix the address', owner: $('Config').first().json.list_editor })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Step 2: each measure's outcome. Step 5 compares with the line; step 9 picks the line in force.
const cfg = $('Config').first().json;
const version = $('Read the version').first().json;
if (version.status !== 'written') return [];
const rows = $('Read the table rows').first().json.items || [];
const lines = $('Read the threshold list').first().json.items || [];
const versions = $('Read versions').first().json.items || [];
const all = $('Read earlier rows').first().json.items || [];
const FAILED = ['stale', 'format changed', 'does not reconcile'];
const WEEK = 7 * 86400000;

// Step 9: a line version is in force for a week only if its system-stamped approval came before that
// week's counting period began (the previous cut-off): it takes effect from the next cut-off after approval.
function lineFor(measure, cutoff) {
  const start = new Date(cutoff).getTime() - WEEK;
  return lines.filter(l => l.measure === measure && l.approved_at && new Date(l.approved_at).getTime() <= start)
    .sort((a, b) => Number(a.version) - Number(b.version)).pop() || null;
}
// Step 5: compare the value or the change with the line, in its direction; "inclusive" says whether landing on it counts.
function past(row, line) {
  const x = row[line.field];
  if (typeof x !== 'number') return false;
  if (line.direction === 'above') return line.inclusive ? x >= line.line : x > line.line;
  return line.inclusive ? x <= line.line : x < line.line;
}
// The optional second-week rule reads the current version of the week before.
const seq = v => Number(String(v.id).replace(/\D/g, '')) || 0;
const prev = versions.filter(v => v.status === 'written' && v.week < version.week).sort((a, b) => seq(a) - seq(b)).pop();
const prevRows = prev ? all.filter(r => r.version === prev.id) : [];

return rows.map(row => {
  const line = lineFor(row.measure, row.cutoff);
  const base = { week: row.week, version: row.version, measure: row.measure, value: row.value, change: row.change,
                 cutoff: row.cutoff, source: row.source, source_link: row.source_link, status: row.status, last_good: row.last_good || null,
                 line_version: line ? line.version : null, line: line ? line.line : null, field: line ? line.field : null,
                 direction: line ? line.direction : null, inclusive: line ? !!line.inclusive : null,
                 measure_owner: line ? line.measure_owner : null, data_owner: line ? line.data_owner : null };
  let outcome;
  if (String(row.status).startsWith('fewer than')) outcome = 'not checked';  // Table 12.2: never checked
  else if (!line) outcome = 'no line';
  else if (FAILED.includes(row.status)) outcome = 'stale';
  else if (!past(row, line)) outcome = 'within the line';
  else if (cfg.second_week_only) {
    const before = prevRows.find(r => r.measure === row.measure);
    const prevLine = before ? lineFor(before.measure, before.cutoff) : null;
    outcome = before && prevLine && past(before, prevLine) ? 'past the line' : 'past the line, first week';
  } else outcome = 'past the line';
  return { json: Object.assign(base, { outcome, key: `${row.week}:${row.measure}:${line ? line.version : 'none'}:${outcome}` }) };
});
};
return { items: one(__rule()).map(o => Object.assign({}, o, BODIES(o))) };
